-- +goose Up
-- Public tokens are generated by the service (platform.NewPublicToken): the gentasks role cannot use core's token function (rule 53).
CREATE TABLE boards (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    token      text NOT NULL UNIQUE,
    name       text NOT NULL,
    created_by text NOT NULL,
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    deleted_at timestamptz
);

CREATE TABLE board_columns (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    token      text NOT NULL UNIQUE,
    board_id   bigint NOT NULL REFERENCES boards (id),
    preset     text CHECK (preset IN ('backlog', 'todo', 'done')),
    name       text,
    position   integer NOT NULL CHECK (position >= 0),
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    deleted_at timestamptz,
    CHECK (preset IS NOT NULL OR name IS NOT NULL)
);

CREATE INDEX board_columns_board_position_idx ON board_columns (board_id, position) WHERE deleted_at IS NULL;

CREATE TABLE labels (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    token      text NOT NULL UNIQUE,
    board_id   bigint NOT NULL REFERENCES boards (id),
    name       text NOT NULL,
    color      text NOT NULL CHECK (color IN ('gray', 'red', 'orange', 'yellow', 'green', 'teal', 'blue', 'purple', 'pink')),
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    deleted_at timestamptz
);

CREATE UNIQUE INDEX labels_board_name_idx ON labels (board_id, lower(name)) WHERE deleted_at IS NULL;

CREATE TABLE tasks (
    id                  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    token               text NOT NULL UNIQUE,
    board_id            bigint NOT NULL REFERENCES boards (id),
    column_id           bigint NOT NULL REFERENCES board_columns (id),
    title               text NOT NULL,
    description         text,
    assignee_user_token text,
    urgency             text NOT NULL DEFAULT 'none' CHECK (urgency IN ('none', 'low', 'medium', 'high', 'urgent')),
    position            integer CHECK (position >= 0),
    created_by          text NOT NULL,
    created_at          timestamptz NOT NULL,
    updated_at          timestamptz NOT NULL,
    archived_at         timestamptz,
    deleted_at          timestamptz,
    -- Only active tasks hold a position; archived and deleted ones leave the column order.
    CHECK ((position IS NOT NULL) = (archived_at IS NULL AND deleted_at IS NULL))
);

CREATE INDEX tasks_column_position_idx ON tasks (column_id, position) WHERE position IS NOT NULL;
CREATE INDEX tasks_board_archived_idx ON tasks (board_id, archived_at) WHERE archived_at IS NOT NULL AND deleted_at IS NULL;

-- Association rows are physically deleted when a label is detached (documented exception to rule 22).
CREATE TABLE task_labels (
    id       bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    token    text NOT NULL UNIQUE,
    task_id  bigint NOT NULL REFERENCES tasks (id),
    label_id bigint NOT NULL REFERENCES labels (id),
    UNIQUE (task_id, label_id)
);

CREATE INDEX task_labels_label_idx ON task_labels (label_id);

-- +goose Down
DROP TABLE task_labels;
DROP TABLE tasks;
DROP TABLE labels;
DROP TABLE board_columns;
DROP TABLE boards;
